<script lang="ts">import {page} from '$app/stores';import {goto} from '$app/navigation';import Heading from '$lib/components/Heading.svelte';import Stat from '$lib/components/Stat.svelte';import StorageForm from '$lib/components/files/StorageForm.svelte';import {fileState,removeSpace} from '$lib/files/store';import {sizeLabel,treeBytes} from '$lib/files/model.js';let edit=false,error='',confirm='',notice='';$: space=$fileState.spaces.find(s=>s.id===$page.params.id);$: used=space?treeBytes(space.files):0;async function copy(){try{await navigator.clipboard.writeText('https://storage.drevanta.example');notice='Sample endpoint copied.';}catch{notice='Could not copy. Select the endpoint manually.';}}function remove(){try{if(!space||confirm!==space.name)return;removeSpace(space.id);void goto('/storage');}catch(e){error=e instanceof Error?e.message:'Unable to delete storage.';}}</script>
{#if space}<Heading title={space.name} subtitle="Storage space · independent of projects"><a class="btn primary" href={'/file-manager?target='+encodeURIComponent('space:'+space.id)}>Open files</a><button class="btn secondary" on:click={()=>edit=!edit}>Settings</button></Heading><div class="stack"><div class="grid3"><Stat label="Stored files" value={Object.values(space.files).filter(f=>f.kind==='file').length} icon="File" hint="Browser sample files"/><Stat label="Used space" value={sizeLabel(used)} icon="Storage" hint={'Quota: '+space.quota+' MB'}/><Stat label="Access" value={space.access} icon="Certificates" hint="Private by default"/></div>{#if edit}<StorageForm {space} onSaved={()=>edit=false} onCancel={()=>edit=false}/>{/if}<section class="card stack"><div><h3>Connection details</h3><p class="subtitle">Illustrative object storage API · not a live endpoint.</p></div><div class="summary-list"><div><span>Bucket</span><strong>{space.id}</strong></div><div><span>API endpoint</span><strong>https://storage.drevanta.example</strong></div><div><span>Access</span><strong>{space.access}</strong></div><div><span>Authentication</span><strong>API credentials / signed URLs (planned)</strong></div></div><div><button class="btn secondary" on:click={copy}>Copy sample endpoint</button></div>{#if notice}<small role="status">{notice}</small>{/if}</section><section class="card"><h3>Storage allocation</h3><p class="subtitle">Quota is a maximum, not preallocated disk space.</p><div class="native-meter"><i style={'width:'+Math.min(100,used/(space.quota*1048576)*100)+'%'}></i></div><div class="row between"><small>{sizeLabel(used)} used</small><small>{space.quota} MB limit</small></div></section><div class="callout"><strong>Application integration</strong><p>A future S3-compatible service will support authenticated object uploads and downloads. No credentials or live endpoints are created in this browser demo.</p></div><section class="card stack"><h3>Delete storage space</h3><p class="subtitle">Removes this space and all its sample files.</p><label class="field">Type {space.name} to confirm<input bind:value={confirm}/></label><div><button class="btn danger" disabled={confirm!==space.name} on:click={remove}>Delete storage</button></div>{#if error}<p class="error" role="alert">{error}</p>{/if}</section></div>{:else}<Heading title="Storage not found" subtitle="The space may have been deleted."/><a class="btn secondary" href="/storage">All storage spaces</a>{/if}
